<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import AppShell from '../components/AppShell.vue'
import TrendChart from '../components/TrendChart.vue'
import { api } from '../api'
import type { DashboardOverview, Statistics } from '../api/types'
import { useAuthStore } from '../stores/auth'
import { errorText, money, todayIso } from '../utils/format'
import { Activity, ArrowDownLeft, ArrowUpRight, CreditCard, RefreshCw, Users } from '@lucide/vue'
const auth=useAuthStore(), today=todayIso(), from=ref(`${today.slice(0,7)}-01`), to=ref(today), stats=ref<Statistics|null>(null), trend=ref<DashboardOverview|null>(null), loading=ref(false), error=ref(''), dateError=ref('')
const comparisonMax=computed(()=>Math.max(Number(stats.value?.rechargeAmount||0),Number(stats.value?.consumptionAmount||0)))
function barWidth(value:string|undefined){return comparisonMax.value>0?Math.max(0,Number(value||0)/comparisonMax.value*100):0}
async function load(){error.value='';dateError.value='';if(from.value&&to.value&&from.value>to.value){dateError.value='结束日期不能早于开始日期';return}loading.value=true;const g=auth.generation;try{const [s,d]=await Promise.all([api.statistics(from.value||undefined,to.value||undefined),api.dashboard(30)]);if(g===auth.generation){stats.value=s;trend.value=d}}catch(e){if(g===auth.generation)error.value=errorText(e)}finally{if(g===auth.generation)loading.value=false}}
onMounted(load)
</script>
<template><AppShell><section class="page-heading"><div><span class="eyebrow">管理工作台</span><h1>运营统计</h1><p>汇总学生账户、校园卡余额与指定日期范围的资金流动。</p></div><button class="button button-secondary" :disabled="loading" @click="load"><RefreshCw :size="16" :class="loading?'spin':''"/> 刷新</button></section>
  <section class="surface-card filter-card statistics-filter"><div class="filter-card-heading"><div><span class="filter-icon"><Activity :size="17"/></span><b>统计日期范围</b></div><small>开始日与结束日均包含</small></div><div class="date-filter-row"><label class="filter-field"><span>开始日期</span><input v-model="from" type="date"/></label><span class="date-dash">—</span><label class="filter-field"><span>结束日期</span><input v-model="to" type="date"/></label><button class="button button-primary" :disabled="loading" @click="load">{{loading?'统计中…':'查看统计'}}</button></div><p v-if="dateError" class="field-error">{{dateError}}</p></section>
  <div v-if="error" class="page-alert"><span>{{error}}</span><button class="button button-small" @click="load">重试</button></div>
  <template v-if="stats"><section class="stats-metric-grid"><article class="metric-card"><span class="metric-icon blue-icon"><Users :size="18"/></span><span class="metric-label">学生用户数</span><strong>{{stats.users}}</strong><small>不含管理员</small></article><article class="metric-card"><span class="metric-icon mint-icon"><Activity :size="18"/></span><span class="metric-label">启用用户</span><strong>{{stats.enabledUsers}}</strong><small>当前有效账户</small></article><article class="metric-card"><span class="metric-icon violet-icon"><CreditCard :size="18"/></span><span class="metric-label">校园卡总余额</span><strong>{{money(stats.totalBalance)}}</strong><small>包含停用账户</small></article><article class="metric-card"><span class="metric-icon amber-icon"><Activity :size="18"/></span><span class="metric-label">范围内交易笔数</span><strong>{{stats.transactionCount}}</strong><small>充值与消费</small></article></section>
    <section class="statistics-grid"><article class="surface-card comparison-card"><div class="section-heading"><div><h2>资金流动</h2><p>{{from||'全部日期'}} 至 {{to||'今天'}}</p></div></div><div class="flow-total"><div><span class="flow-indicator mint"></span><span>充值总额</span><b>{{money(stats.rechargeAmount)}}</b></div><div><span class="flow-indicator amber"></span><span>消费总额</span><b>{{money(stats.consumptionAmount)}}</b></div></div><div class="compare-bars"><div class="compare-row"><span>充值</span><div class="compare-track"><i class="compare-fill recharge-fill" :style="{width:barWidth(stats.rechargeAmount)+'%'}"></i></div><b>{{money(stats.rechargeAmount)}}</b></div><div class="compare-row"><span>消费</span><div class="compare-track"><i class="compare-fill consume-fill" :style="{width:barWidth(stats.consumptionAmount)+'%'}"></i></div><b>{{money(stats.consumptionAmount)}}</b></div></div><p class="chart-footnote">柱长按两项实际金额的比例显示。</p></article><article class="surface-card statistics-trend-card"><div class="section-heading"><div><h2>每日交易趋势</h2><p>最近 30 日</p></div></div><TrendChart :points="trend?.trend||[]" :compact="true"/></article></section>
  </template><div v-else-if="loading" class="loading-panel"><span class="spinner"></span><span>正在汇总统计数据…</span></div>
</AppShell></template>
